scripts.search-prior:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'search-prior',
  description:
    'Search project memory for prior investigations matching a symptom signature. Stamps {matches: number, hits: [{text, score}]}.',
  inputs: {
    symptom: {
      type: 'string',
      description: 'Short symptom description (1-3 sentences). Used as the search query.',
      required: true,
    },
  },
  outputs: {
    matches: { type: 'number', description: 'Number of memory hits returned.' },
    hits: {
      type: 'array',
      description: 'Top matches, each with text + score.',
      itemType: 'object',
    },
  },
  requires: ['memory.read'],
});

interface MemoryHit {
  text: string;
  score: number;
}

async function main(): Promise<void> {
  const input = gezel.input as { symptom: string };
  const query = `investigation: ${input.symptom}`;
  const results = (await gezel.memory.search(query)) as MemoryHit[];
  const filtered = (results ?? []).filter(
    (r): r is MemoryHit => Boolean(r) && typeof r.text === 'string' && typeof r.score === 'number',
  );
  gezel.log(`Memory search for "${query}" returned ${filtered.length} hit(s)`);
  gezel.output({ matches: filtered.length, hits: filtered.slice(0, 5) });
}

await main();

scripts.save-learning:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'save-learning',
  description:
    'Stamp a (symptom → root cause → fix) investigation triple into project memory so future `search-prior` queries find it.',
  inputs: {
    symptom: { type: 'string', description: 'Observable failure.', required: true },
    rootCause: { type: 'string', description: 'Root cause in one sentence.', required: true },
    fix: { type: 'string', description: 'Proposed fix.', required: true },
    files: {
      type: 'string',
      description: 'Comma-separated list of files touched (or expected to be touched).',
    },
  },
  outputs: {
    ok: { type: 'boolean', description: 'True on successful save.' },
  },
  requires: ['memory.write'],
});

async function main(): Promise<void> {
  const input = gezel.input as {
    symptom: string;
    rootCause: string;
    fix: string;
    files?: string;
  };
  const text = [
    'investigation:',
    `symptom: ${input.symptom}`,
    `root cause: ${input.rootCause}`,
    `fix: ${input.fix}`,
    ...(input.files ? [`files: ${input.files}`] : []),
  ].join('\n');
  await gezel.memory.save(text, {
    kind: 'investigation',
    ...(input.files ? { files: input.files } : {}),
  });
  gezel.log('Saved investigation to memory.');
  gezel.output({ ok: true });
}

await main();
